import {api,token,personal,message} from './common.js';
const status=document.querySelector('#rsvp-status'),name=document.querySelector('#guest-name');
document.querySelector('#gifts-link').href=personal('/presentes/');
const whatsapp=document.querySelector('#whatsapp-link');
function wa(guest='',rsvp=''){whatsapp.href='https://wa.me/258848675125?text='+encodeURIComponent(`Olá Aniceta! Sou ${guest||'um convidado'}. ${rsvp==='yes'?'Confirmo a minha presença':rsvp==='no'?'Infelizmente não poderei estar presente':'Gostaria de falar sobre a confirmação de presença'} no vosso casamento de 20/02/2027.`)}wa();
async function load(){if(!token){name.textContent='Será uma alegria receber você.';status.textContent='Abra o link pessoal enviado pelos noivos para confirmar a presença.';return}try{const {guest}=await api('/api/invite');name.textContent=`${guest.name}, este convite é para você.`;wa(guest.name,guest.rsvp);status.textContent=guest.rsvp==='yes'?'A sua presença está confirmada.':guest.rsvp==='no'?'Registámos que não poderá estar presente.':'Por favor, confirme a sua presença.';document.querySelector('#rsvp-actions').hidden=false;for(const b of document.querySelectorAll('[data-rsvp]'))b.onclick=async()=>{const buttons=document.querySelectorAll('[data-rsvp]');buttons.forEach(x=>x.disabled=true);try{await api('/api/rsvp',{method:'POST',body:{rsvp:b.dataset.rsvp}});await load();await message(b.dataset.rsvp==='yes'?'Presença confirmada. Obrigado!':'Resposta registada. Obrigado por avisar.')}catch(e){await message(e.message)}finally{buttons.forEach(x=>x.disabled=false)}}}catch(e){status.textContent=e.message;document.querySelector('#rsvp-actions').hidden=true}}load();
const audio=document.querySelector('#wedding-music'),toggle=document.querySelector('#music-toggle');audio.volume=.45;
async function play(){try{await audio.play()}catch{toggle.textContent='♫ Ouvir música'}}
audio.addEventListener('play',()=>toggle.textContent='Ⅱ Pausar música');audio.addEventListener('pause',()=>toggle.textContent='♫ Ouvir música');audio.addEventListener('error',()=>{toggle.textContent='Música indisponível';toggle.disabled=true});toggle.onclick=()=>audio.paused?play():audio.pause();
play();document.addEventListener('pointerdown',function start(e){if(e.target===toggle)return;if(audio.paused)play()},{once:true});
